def is_code(n):
    for s,e in code_ranges:
        if s <= n <= e:
            return True
    return False

def is_fm(n):
    return 1 <= n <= 7

# For each line with a hyphen, print every hyphen occurrence with context
for i, line in enumerate(lines, 1):
    raw = line.rstrip('\n')
    if '-' not in raw:
        continue

    # Find all hyphen positions
    positions = [j for j, ch in enumerate(raw) if ch == '-']

    # Determine zone
    if is_fm(i):
        zone = 'FRONTMATTER'
    elif is_code(i):
        zone = 'CODE'
    else:
        zone = 'PROSE'

    print(f'LINE {i} [{zone}]: {raw[:120]}{"..." if len(raw)>120 else ""}')

    # Group consecutive hyphens
    groups = []
    current_group = [positions[0]]
    for p in positions[1:]:
        if p == current_group[-1] + 1:
            current_group.append(p)
        else:
            groups.append(current_group)
            current_group = [p]
    groups.append(current_group)

    for g in groups:
        start = g[0]
        end = g[-1]
        length = len(g)
        # Get surrounding context (10 chars each side)
        ctx_start = max(0, start - 15)
        ctx_end = min(len(raw), end + 16)
        context = raw[ctx_start:ctx_end]

        # Extract the "word" containing the hyphen
        # find word boundary before first hyphen
        ws = start
        while ws > 0 and raw[ws-1] not in ' \t,;:()[]{}"\'><=!':
            ws -= 1
        we = end + 1
        while we < len(raw) and raw[we] not in ' \t,;:()[]{}"\'><=!':
            we += 1
        word = raw[ws:we]

        if length == 3 and raw.strip() == '---':
            if i == 1 or i == 7:
                cat = 'FRONTMATTER'
            elif i == 16:
                cat = 'HEADING_DASH'
            else:
                cat = 'HEADING_DASH'
        elif zone == 'FRONTMATTER':
            cat = 'FRONTMATTER'
        elif zone == 'CODE':
            cat = 'CODE'
        else:
            cat = f'  [needs manual classification: "{word}"]'

        print(f'  pos {start}-{end} ({length} hyphens): "{word}" -> {cat}')

    print()

